async function hashPin(pin,salt){
 const enc=new TextEncoder(),key=await crypto.subtle.importKey('raw',enc.encode(pin),'PBKDF2',false,['deriveBits']);
 const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:enc.encode(salt),iterations:160000,hash:'SHA-256'},key,256);
 return [...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,'0')).join('');
}
async function setPin(pin){const salt=crypto.randomUUID();return writeLocal('hibiki.pin',{salt,hash:await hashPin(pin,salt)});}
async function checkPin(pin){const saved=readLocal('hibiki.pin',null);return !!saved&&await hashPin(pin,saved.salt)===saved.hash;}
