function trackHTML(t,i){return `<div class="track" data-id="${esc(t.id)}"><span class="track-number">${String(i+1).padStart(2,'0')}</span><div class="track-main"><div class="cover">${art(t)}</div><div class="trackinfo"><b>${esc(t.title)}</b><small>${esc(t.artist||'Artiste inconnu')}${t.remoteOnly?' · Audio sur un autre appareil':''}</small></div></div><span class="duration">${t.duration?time(t.duration):'—'}</span><div class="track-actions"><button class="heart ${favorites.has(t.id)?'on':''}" data-heart="${esc(t.id)}" aria-label="${favorites.has(t.id)?'Retirer des':'Ajouter aux'} favoris">${icon('heart')}</button><button class="iconbtn" data-enqueue="${esc(t.id)}" aria-label="Ajouter à la file">＋</button><button class="iconbtn" data-edit-track="${esc(t.id)}" aria-label="Modifier les métadonnées">⋯</button></div></div>`}
