function formatOf(t){const raw=t.mime||t.blob?.type||t.url||'';const m=String(raw).match(/(?:audio\/|\.)([a-z0-9]{2,5})(?:$|[;?])/i);return (m?.[1]||'inconnu').replace('mpeg','mp3').toLowerCase()}
function renderLibrary(){let list=[...tracks],f=$('#libraryFilter')?.value.toLocaleLowerCase()||'',field=$('#libraryField')?.value||'all',format=$('#formatFilter')?.value||'all';list=list.filter(t=>{const title=(t.title||'').toLocaleLowerCase(),artist=(t.artist||'').toLocaleLowerCase();return(!f||(field==='title'?title:field==='artist'?artist:title+' '+artist).includes(f))&&(format==='all'||formatOf(t)===format)});let sort=$('#sortSelect')?.value||'added';list.sort((a,b)=>sort==='title'?(a.title||'').localeCompare(b.title||''):sort==='artist'?(a.artist||'').localeCompare(b.artist||''):((b.added||0)-(a.added||0)));const count=$('#libraryCount');if(count)count.textContent=`${list.length} / ${tracks.length} morceau${tracks.length!==1?'x':''}`;const select=$('#formatFilter');if(select){const selected=select.value,formats=[...new Set(tracks.map(formatOf))].sort();select.innerHTML='<option value="all">Tous les formats</option>'+formats.map(x=>`<option value="${esc(x)}">${esc(x.toUpperCase())}</option>`).join('');select.value=formats.includes(selected)?selected:'all'}$('#libraryTracks').innerHTML=list.length?list.map(trackHTML).join(''):`<div class="empty"><div class="big">${icon('music')}</div>${tracks.length?'Aucun morceau ne correspond aux filtres.':'Ta bibliothèque est encore vide.<br>Ajoute tes premiers morceaux !'}</div>`;bindTracks('#libraryTracks')}
