$$('[data-mood]').forEach(btn=>btn.onclick=()=>{$$('[data-mood]').forEach(x=>x.classList.toggle('active',x===btn));const mood=btn.dataset.mood;const keys={calm:/ambient|lofi|chill|piano|acoustic|calme/i,focus:/instrumental|classical|ambient|study|focus/i,energy:/rock|dance|electro|metal|pop|energy/i,night:/night|dark|dream|sleep|lofi/i};let list=[...tracks].sort((a,b)=>(b.lastPlayed||b.added||0)-(a.lastPlayed||a.added||0));if(keys[mood])list=list.filter(t=>keys[mood].test((t.title||'')+' '+(t.artist||'')));const el=$('#recentTracks');if(el){const chosen=list.slice(0,5);el.innerHTML=chosen.length?chosen.map(trackHTML).join(''):`<div class="empty">${mood==='all'?'Tes écoutes récentes apparaîtront ici.':'Pas encore de morceau correspondant à cette ambiance. Ajoute des titres ou essaie une autre ambiance.'}</div>`;bindTracks('#recentTracks')}});
