// Keep profile counters and active profile tabs current as the library changes.
const oldRefreshProfile=refreshProfile;refreshProfile=function(){oldRefreshProfile();if(profileScreen?.classList.contains('open'))refreshFullProfile()};

async function init(){try{if(screen.orientation?.lock)screen.orientation.lock('portrait').catch(()=>{});db=await openDatabase(DB,STORE);tracks=await getAll(STORE);let meta=await getAll('meta');const savedFavorites=meta.find(x=>x.key==='favorites')?.value,savedPlaylists=meta.find(x=>x.key==='playlists')?.value;favorites=new Set(Array.isArray(savedFavorites)?savedFavorites.filter(x=>typeof x==='string'):[]);playlists=Array.isArray(savedPlaylists)?savedPlaylists.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string').map(p=>({...p,ids:Array.isArray(p.ids)?p.ids.filter(x=>typeof x==='string'):[]})):[];const auth=await setupAuth(()=>({profile:hibikiProfile,favorites,playlists,tracks}),remote=>{hibikiProfile={...remote,...Object.fromEntries(Object.entries(hibikiProfile).filter(([,value])=>value!==''&&value!==null&&value!==undefined))};writeLocal('hibiki.profile',hibikiProfile);refreshProfile()},async (remote,remoteTracks=[])=>{for(const row of remoteTracks){if(!row||typeof row.local_id!=='string'||tracks.some(t=>t.id===row.local_id))continue;tracks.push({id:row.local_id,title:row.title||'Titre synchronisé',artist:row.artist||'Artiste inconnu',duration:Number(row.duration)||0,mime:row.mime_type||'',added:Date.parse(row.added_at)||Date.now(),lastPlayed:Date.parse(row.last_played_at)||0,plays:Number(row.play_count)||0,remoteOnly:true})}const remoteFavs=Array.isArray(remote.favorites)?remote.favorites.filter(x=>typeof x==='string'):[];favorites=new Set([...favorites,...remoteFavs]);if(Array.isArray(remote.playlists)){for(const item of remote.playlists){if(item&&typeof item.id==='string'&&typeof item.name==='string'&&!playlists.some(p=>p.id===item.id))playlists.push({id:item.id,name:item.name,desc:item.description||'',ids:Array.isArray(item.track_ids)?item.track_ids.filter(x=>typeof x==='string'):[]})}}await saveMeta();renderLibrary();renderFavorites();renderPlaylists();stats()});authSync=auth.sync;stats();renderLibrary();setupVisualizer();refreshProfile();$('#pinStatus').textContent=readLocal('hibiki.pin',null)?'Verrouillage activé · code à 4 chiffres':'Verrouillage désactivé';lockScreen();$('#greeting').textContent=(new Date().getHours()<18?'BONJOUR':'BONSOIR')+' · ようこそ';if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&screen.orientation?.lock)screen.orientation.lock('portrait').catch(()=>{})});}catch(e){storageFailure('IndexedDB initialization',e);toast(`Bibliothèque inaccessible : ${e?.message||'stockage local indisponible'}. Recharge après avoir vérifié les réglages du navigateur.`)}}init();
